// Dropdown "Charge Control" -> mode
// Order = order of options in the switch node
var MODES = ['auto', 'manual_schon', 'manual_frei'];   // Auto Charge | Manual Conservation | Manual Free

if (msg.source_path !== '/SwitchableOutput/output_1/Dimming') return null;
var modus = MODES[Number(msg.payload)];
if (!modus) return null;

if (context.get('lastModus') === modus) return null;
context.set('lastModus', modus);

node.status({ fill: modus === 'auto' ? 'blue' : 'yellow', shape: 'dot', text: modus });
return { topic: 'modus', payload: modus };

// =====================
// Full Charge Logic — v4
// See tab info for model description.
// Inputs:   msg.topic "modus" (auto | manual_frei | manual_schon)
//           msg.topic "param_float"    (conservation voltage from GX)
//           msg.topic "param_interval" (interval in weeks from GX)
//           msg.topic "heartbeat"
//           number = CVL from JK-BMS
// Outputs:  1 DVCC voltage | 2 History (JSON) | 3 Charge indicator (0/1)
//           4 Last Full Charge indicator (label = date/time, value = days) | 5 VRM event
//           6 Conservation voltage indicator (VRM only) | 7 Full charge interval indicator (VRM only)
// =====================

var DELTA_V = 0.5;                    // CVL drop that counts as full charge

// Conservation voltage and interval come from GX (group Full Charge Control).
// Limits and fallback values if nothing valid has been received:
var FLOAT_MIN = 52.0, FLOAT_MAX = 54.4, FLOAT_DEFAULT = 53.9;
var INTERVAL_MIN = 1, INTERVAL_MAX = 8, INTERVAL_DEFAULT = 2;

function floatVoltage() {
    var v = context.get('floatV');
    return (typeof v === 'number' && v >= FLOAT_MIN && v <= FLOAT_MAX) ? v : FLOAT_DEFAULT;
}
function intervalWeeks() {
    var w = context.get('intervalW');
    return (typeof w === 'number' && w >= INTERVAL_MIN && w <= INTERVAL_MAX) ? w : INTERVAL_DEFAULT;
}

var DAY = 86400000;
var now = new Date();
function pad(n) { return ('0' + n).slice(-2); }
var today = now.getFullYear() + '-' + pad(now.getMonth() + 1) + '-' + pad(now.getDate());
var nowT = pad(now.getHours()) + ':' + pad(now.getMinutes());

function dayUTC(s) { var p = s.split('-'); return Date.UTC(+p[0], +p[1] - 1, +p[2]); }
function mondayUTC(s) { var t = dayUTC(s); return t - ((new Date(t).getUTCDay() + 6) % 7) * DAY; }
function getKW(date) {
    var d = new Date(Date.UTC(date.getFullYear(), date.getMonth(), date.getDate()));
    var dayNum = d.getUTCDay() || 7;
    d.setUTCDate(d.getUTCDate() + 4 - dayNum);
    var yearStart = new Date(Date.UTC(d.getUTCFullYear(), 0, 1));
    return Math.ceil((((d - yearStart) / DAY) + 1) / 7);
}
function sendIfChanged(key, val) {
    if (context.get(key) === val) return null;
    context.set(key, val);
    return { payload: val };
}

var MODUS_TEXT = { auto: 'AUTO', manual_frei: 'MANUAL', manual_schon: 'MANUAL' };

function evaluate(detected) {
    var modus = context.get('modus') || 'auto';
    var history = flow.get('volladung_history') || [];
    var msgHist = null, msgEvent = null;

    if (detected) {
        history.push({ kw: getKW(now), year: now.getFullYear(), date: today, time: nowT, quelle: detected.quelle });
        flow.set('volladung_history', history);
        msgHist = { payload: JSON.stringify(history, null, 2) };
        msgEvent = { payload: 'Full charge detected (' + (detected.quelle === 'auto' ? 'Auto' : 'Manual') +
            '): CVL ' + detected.von.toFixed(2) + ' V -> ' + detected.nach.toFixed(2) + ' V' };
    }

    var last = history.length ? history[history.length - 1] : null;
    var lastDate = (last && typeof last.date === 'string') ? last.date : null;
    var weeks = lastDate ? Math.round((mondayUTC(today) - mondayUTC(lastDate)) / (7 * DAY)) : null;
    var days = lastDate ? Math.floor((dayUTC(today) - dayUTC(lastDate)) / DAY) : null;

    var FLOAT_VOLTAGE = floatVoltage();
    var FULL_CHARGE_INTERVAL_WEEKS = intervalWeeks();
    // Extended interval during ongoing full charge -> abort, switch to conservation (intended)
    var dvcc;
    if (modus === 'manual_frei') dvcc = 0;
    else if (modus === 'manual_schon') dvcc = FLOAT_VOLTAGE;
    else dvcc = (weeks === null || weeks >= FULL_CHARGE_INTERVAL_WEEKS) ? 0 : FLOAT_VOLTAGE;
    context.set('lastDVCC', dvcc);

    var frei = dvcc === 0 ? 1 : 0;

    var msgLadung = sendIfChanged('ind_ladung', frei);
    // Display value is numeric only -> date/time of history entry is in left label
    var msgLetzte = null;
    if (lastDate) {
        var p = lastDate.split('-');
        var title = p[2] + '.' + p[1] + '.' + p[0] + (last.time ? ' ' + last.time : '');
        if (context.get('ind_letzte') !== title + '|' + days) {
            context.set('ind_letzte', title + '|' + days);
            msgLetzte = { payload: { 'GenericInput/0/Settings/CustomName': 'Last Full Charge', 'GenericInput/0/Settings/PrimaryLabel': title, 'Value': days } };
        }
    }

    var cvl = context.get('lastCVL');
    var peak = context.get('peakCVL');
    node.status({
        fill: detected ? 'green' : (frei ? 'blue' : 'grey'),
        shape: 'dot',
        text: (detected ? '✓ FULL CHARGE | ' : '') +
            MODUS_TEXT[modus] + ' · ' + (frei ? 'FREE' : 'CONS') +
            ' | DVCC ' + dvcc + 'V' +
            ' | Cons ' + FLOAT_VOLTAGE + 'V · ' + FULL_CHARGE_INTERVAL_WEEKS + 'W' +
            (typeof cvl === 'number' ? ' | CVL ' + cvl.toFixed(2) + ' (Peak ' + peak.toFixed(2) + ')' : '') +
            ' | last ' + (lastDate ? lastDate + (last.time ? ' ' + last.time : '') + (last.quelle ? ' ' + last.quelle : '') + ', ' + days + 'd' : '–') +
            ' | ' + nowT
    });

    // Active parameters for read-only display in VRM
    var msgFV = sendIfChanged('ind_float', FLOAT_VOLTAGE);
    var msgIV = sendIfChanged('ind_interval', FULL_CHARGE_INTERVAL_WEEKS);

    return [{ payload: dvcc }, msgHist, msgLadung, msgLetzte, msgEvent, msgFV, msgIV];
}

// ----- Parameters from GX -----
if (msg.topic === 'param_float' || msg.topic === 'param_interval') {
    var val = Number(msg.payload);
    if (msg.topic === 'param_float') {
        val = Math.round(val * 10) / 10;
        if (!(val >= FLOAT_MIN && val <= FLOAT_MAX)) {
            node.warn('Conservation voltage ' + msg.payload + ' outside ' + FLOAT_MIN + '–' + FLOAT_MAX + ' V, ignored');
            return null;
        }
        context.set('floatV', val);
    } else {
        val = Math.round(val);
        if (!(val >= INTERVAL_MIN && val <= INTERVAL_MAX)) {
            node.warn('Interval ' + msg.payload + ' outside ' + INTERVAL_MIN + '–' + INTERVAL_MAX + ' weeks, ignored');
            return null;
        }
        context.set('intervalW', val);
    }
    if (!flow.get('volladung_history_ready')) {
        node.status({ fill: 'yellow', shape: 'ring', text: msg.topic + '=' + val + ' stored, waiting for history | ' + nowT });
        return null;
    }
    return evaluate(null);
}

// ----- Mode from switch -----
if (msg.topic === 'modus') {
    if (['auto', 'manual_frei', 'manual_schon'].indexOf(msg.payload) === -1) return null;
    context.set('modus', msg.payload);
    if (!flow.get('volladung_history_ready')) {
        node.status({ fill: 'yellow', shape: 'ring', text: 'Mode ' + msg.payload + ' stored, waiting for history | ' + nowT });
        return null;
    }
    return evaluate(null);
}

// ----- Guard: history must be loaded -----
if (!flow.get('volladung_history_ready')) {
    node.status({ fill: 'yellow', shape: 'ring', text: 'waiting for history | ' + nowT });
    return null;
}

// ----- Heartbeat: re-evaluate interval (week change), no detection -----
if (msg.topic === 'heartbeat') return evaluate(null);

// ----- CVL -----
if (typeof msg.payload !== 'number') return null;
var cvlNow = msg.payload;

var lastSeen = context.get('lastSeenCVL');
if (lastSeen !== undefined && cvlNow === lastSeen) return null;   // duplicate
context.set('lastSeenCVL', cvlNow);
context.set('lastCVL', cvlNow);

var peakNow = context.get('peakCVL');
if (peakNow === undefined) peakNow = cvlNow;   // after restart: current value as baseline

var detected = null;
if (peakNow - cvlNow >= DELTA_V) {
    // Full charge only counts when Free is currently active – same in Auto and Manual
    if (context.get('lastDVCC') === 0) {
        detected = { quelle: (context.get('modus') || 'auto') === 'auto' ? 'auto' : 'manual', von: peakNow, nach: cvlNow };
    }
    peakNow = cvlNow;
}
if (cvlNow > peakNow) peakNow = cvlNow;
context.set('peakCVL', peakNow);

return evaluate(detected);

var d = new Date();
var t = ('0'+d.getHours()).slice(-2)+':'+
        ('0'+d.getMinutes()).slice(-2)+':'+
        ('0'+d.getSeconds()).slice(-2);

var count = context.get('writeCount') || 0;
count++;
context.set('writeCount', count);

var v = msg.payload;
var label = (v === 0) ? 'DVCC=0 (BMS free)' : 'DVCC='+v+'V';

node.status({
    fill: v === 0 ? 'blue' : 'green',
    shape: 'dot',
    text: label+' | writes:'+count+' | '+t
});

return msg;

var d = new Date();
var t = ('0'+d.getHours()).slice(-2)+':'+
        ('0'+d.getMinutes()).slice(-2);

try {
    var history = JSON.parse(msg.payload);
    if (!Array.isArray(history)) throw new Error('not an array');
    flow.set('volladung_history', history);
    flow.set('volladung_history_ready', true);

    var last = history.length > 0 ? history[history.length-1] : null;
    var lastText = last ? ('last: '+last.date+(last.quelle ? ' '+last.quelle : '')) : 'no entries';

    node.status({ fill:'green', shape:'dot',
        text: '✓ '+history.length+' entries | '+lastText+' | loaded '+t });
} catch (e) {
    flow.set('volladung_history', []);
    flow.set('volladung_history_ready', true);
    node.status({ fill:'red', shape:'ring', text:'✗ history empty/invalid | '+t });
}
return null;

var d = new Date();
var t = ('0'+d.getHours()).slice(-2)+':'+
        ('0'+d.getMinutes()).slice(-2)+':'+
        ('0'+d.getSeconds()).slice(-2);
var count = (context.get('writes') || 0) + 1;
context.set('writes', count);
node.status({ fill:'green', shape:'dot',
    text: '✓ written '+d.toISOString().slice(0,10)+' '+t+' | total:'+count });
return null;
